package com.techprotech.agenda.modulos.productos.api;
import com.techprotech.agenda.modulos.productos.api.dto.*;import com.techprotech.agenda.modulos.productos.aplicacion.ServicioComisiones;import com.techprotech.agenda.modulos.productos.seguridad.PermisosComisiones;import com.techprotech.agenda.seguridad.jwt.UsuarioAutenticado;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/comisiones") @PreAuthorize(PermisosComisiones.EXPRESION) public class ControladorComisionesAdmin{private final ServicioComisiones s;public ControladorComisionesAdmin(ServicioComisiones s){this.s=s;}@GetMapping public CatalogoComisionesResponse get(@AuthenticationPrincipal UsuarioAutenticado u){return s.catalogo(u.empresaId());}@PostMapping public ReglaComisionResponse post(@AuthenticationPrincipal UsuarioAutenticado u,@Valid @RequestBody ReglaComisionRequest r){return s.crear(u.empresaId(),r);}@PatchMapping("/{id}")public ReglaComisionResponse patch(@AuthenticationPrincipal UsuarioAutenticado u,@PathVariable Long id,@Valid @RequestBody ReglaComisionRequest r){return s.actualizar(u.empresaId(),id,r);}}
